import zipfile, json, re, os

# Prefer lxml; fall back to stdlib
try:
    from lxml import etree  # type: ignore
    LXML = True
except Exception:
    import xml.etree.ElementTree as etree  # type: ignore
    LXML = False

# Paths
TEMPLATE = '/root/training_feedback_template.hwpx'
JSON_FILE = '/root/training_feedback.json'
OUTPUT = '/root/training_feedback_ready.hwpx'


def localname(tag: str) -> str:
    """Return localname from an expanded or prefixed tag."""
    if tag is None:
        return ''
    if '}' in tag:
        return tag.split('}', 1)[1]
    return tag


def digits_only(val) -> str:
    if val is None:
        return ''
    s = str(val)
    return ''.join(ch for ch in s if ch.isdigit())


def parse_satisfaction(val) -> str:
    """Rewrite 만족도 as 'X.X점 (5.0점 만점)' using numeric score from JSON."""
    if val is None:
        score = ''
    else:
        s = str(val).strip()
        # Common inputs: '4.5/5.0', '4.5', 4.5
        m = re.search(r'(\d+(?:\.\d+)?)', s)
        score = m.group(1) if m else s
    return f"{score}점 (5.0점 만점)"


def build_sub_map(data: dict) -> dict:
    sub = {}
    for k, v in data.items():
        sub[k] = '' if v is None else str(v)

    # Required transforms
    if '참석자수' in data:
        sub['참석자수'] = digits_only(data.get('참석자수'))

    if '만족도' in data:
        sub['만족도'] = parse_satisfaction(data.get('만족도'))

    # Overall opinion append
    # (template uses {{종합의견}})
    if '종합의견' in data:
        base = '' if data.get('종합의견') is None else str(data.get('종합의견'))
        # Ensure exactly one leading space before suffix per requirement
        suffix = ' 후속 심화반 검토 요망.'
        if base.endswith(suffix):
            sub['종합의견'] = base
        else:
            sub['종합의견'] = base + suffix

    return sub


def replace_placeholders_raw(xml_text: str, sub_map: dict) -> tuple[str, set[str]]:
    """Replace {{key}} placeholders in raw XML string. Returns (new_text, used_keys)."""
    used = set()

    def repl(m):
        key = m.group(1)
        used.add(key)
        if key not in sub_map:
            # Leave unknown placeholders unchanged
            return m.group(0)
        return sub_map[key]

    new_text = re.sub(r'\{\{(.*?)\}\}', repl, xml_text)
    return new_text, used


def paragraph_text(p_elem) -> str:
    parts = []
    for t in p_elem.iter():
        if localname(getattr(t, 'tag', '')) == 't':
            if t.text:
                parts.append(t.text)
    return ''.join(parts)


def remove_layout_caches_from_paragraph(p_elem) -> list[str]:
    """Remove conservative set of layout-cache-ish descendants under a paragraph."""
    removed = []

    keywords = [
        'lineseg', 'linesegarray', 'lineSeg', 'lineSegArray',
        'charpr', 'charPr', 'CharPr', 'CharPrIDArray', 'CharPrID',
        'charshape', 'charShape', 'CharShape',
        'textpos', 'pos',
    ]

    # stdlib ElementTree has no getparent(). We rebuild by scanning direct children and known cache nodes.
    # In this template, cache nodes are direct children like <hp:linesegarray>.
    to_remove = []
    for child in list(p_elem):
        ln = localname(child.tag).lower()
        if any(k.lower() in ln for k in keywords):
            to_remove.append(child)

    for child in to_remove:
        removed.append(localname(child.tag))
        p_elem.remove(child)

    return removed


def main():
    # Load JSON
    with open(JSON_FILE, 'r', encoding='utf-8') as f:
        data = json.load(f)

    sub_map = build_sub_map(data)

    # Process zip
    modified_files = []

    with zipfile.ZipFile(TEMPLATE, 'r') as zin:
        with zipfile.ZipFile(OUTPUT, 'w') as zout:
            for info in zin.infolist():
                name = info.filename
                b = zin.read(name)

                if not name.lower().endswith('.xml'):
                    zout.writestr(info, b)
                    continue

                # Decode; if not UTF-8 XML, just copy
                try:
                    xml_text = b.decode('utf-8')
                except Exception:
                    zout.writestr(info, b)
                    continue

                if '{{' not in xml_text:
                    # Still parse? leave alone
                    zout.writestr(info, b)
                    continue

                replaced_text, used_keys = replace_placeholders_raw(xml_text, sub_map)

                # Parse to strip layout caches for paragraphs whose text changed (conservatively: any paragraph containing any used key value)
                try:
                    if LXML:
                        parser = etree.XMLParser(remove_blank_text=False)
                        root = etree.fromstring(replaced_text.encode('utf-8'), parser=parser)
                    else:
                        root = etree.fromstring(replaced_text.encode('utf-8'))
                except Exception as e:
                    raise RuntimeError(f'Failed to parse XML after replacement: {name}: {e}')

                # Find paragraphs and remove caches where placeholder keys appeared in that paragraph
                # We detect modification by searching for any substituted value in the paragraph concatenated text.
                removed_any = False
                removed_log = []

                # Build list of unique replacement values (avoid empty)
                rep_values = [sub_map[k] for k in used_keys if k in sub_map and sub_map[k] != '']

                for p in root.iter():
                    if localname(getattr(p, 'tag', '')) != 'p':
                        continue
                    txt = paragraph_text(p)
                    if not txt:
                        continue
                    if any(v in txt for v in rep_values):
                        removed = remove_layout_caches_from_paragraph(p)
                        if removed:
                            removed_any = True
                            removed_log.append((p.get('id'), removed))

                if removed_any:
                    print(f'{name}: removed layout-cache elements from modified paragraphs:')
                    for pid, removed in removed_log:
                        print(f'  paragraph id={pid}: removed {removed}')
                else:
                    print(f'{name}: no layout-cache elements removed (none matched keywords as direct children)')

                out_bytes = None
                if LXML:
                    out_bytes = etree.tostring(root, xml_declaration=True, encoding='utf-8')
                else:
                    out_bytes = etree.tostring(root, encoding='utf-8', xml_declaration=True)

                # Preserve compression type by writing with a ZipInfo that keeps compress_type
                zi = zipfile.ZipInfo(filename=name, date_time=info.date_time)
                zi.compress_type = info.compress_type
                zi.external_attr = info.external_attr
                zi.internal_attr = info.internal_attr
                zi.flag_bits = info.flag_bits

                zout.writestr(zi, out_bytes)
                modified_files.append(name)

    print('Done. Modified:', modified_files)


if __name__ == '__main__':
    main()

